import{_ as t,o as s,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-8-sign-out/report3_spec.md","filePath":"feature/authentication/3-2-8-sign-out/report3_spec.md"}'),i={name:"feature/authentication/3-2-8-sign-out/report3_spec.md"};function n(a,e,l,c,d,u){return s(),o("div",null,[...e[0]||(e[0]=[r("<p><strong>3.2.8 Sign Out (Logout)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user clicks &quot;Log out&quot; in the account/navbar menu (or the dashboard&#39;s logout button).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated USER.</li><li><strong>Purpose</strong>: End the current session. Blacklists the current access and refresh token server-side and records a LOGOUT audit event, then clears local client state and redirects to /login.</li><li><strong>Interface</strong>: A &quot;Log out&quot; menu item / icon button in the Navbar and in the Dashboard page header.</li><li><strong>Data Processing</strong>: The client fires the logout call (fire-and-forget, not awaited) and, independent of its outcome, immediately clears local auth state and navigates to /login. The backend reads the access token header, the refresh token cookie, and request metadata, blacklists the access token (best-effort) and the refresh token (best-effort), writes an audit log when the access token yielded a user id, clears the refresh cookie, and returns 200.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Sign Out entry points (no dedicated Sign Out screen exists):</p><ul><li>Navbar: a &quot;Log out&quot; icon button inside the account area.</li><li>Dashboard page header: a separate &quot;Log out&quot; button that clears local state directly, without calling the logout endpoint.</li><li>After either action, the user becomes unauthenticated and any protected route redirects to /login.</li><li>A 401 response interceptor also forces logout automatically on session expiry, with toast <strong>MSG22</strong>; this path also does not call the logout endpoint.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required (backend)</strong>: Authorization Bearer header. The refresh token cookie is optional.</li><li><strong>Input optional (backend)</strong>: IP address and user-agent headers, used for the audit record.</li><li><strong>Input (frontend)</strong>: none — no body is sent; the header and cookie are attached automatically.</li><li><strong>System data</strong>: userId resolved from the access token&#39;s subject (only if it parses); the token&#39;s jti for blacklisting; the caller&#39;s ipAddress/userAgent.</li><li><strong>Output</strong>: no payload, 200. The refresh token cookie is cleared.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-14</strong>: Sign-out blacklists both access and refresh token jti values and clears the refresh cookie. Each blacklisting step is independently best-effort — either one failing (expired, malformed, wrong signature) is swallowed silently and does not fail the request. The refresh cookie is cleared unconditionally on every successful response. The frontend call itself is best-effort and swallows any error, proceeding to clear local state regardless.</li><li><strong>BR-16</strong>: Security events (LOGIN, LOGOUT, PASSWORD_RESET) are always persisted to the audit log with IP + user agent. For logout, the audit row is written only if the access token successfully parsed to a userId; otherwise no row is written but success is still reported.</li><li>Only the tokens for the current device/session are invalidated; refresh tokens held by other devices are unaffected, unlike a password change which invalidates every refresh token.</li><li>Missing or malformed Authorization header is the one case that is not best-effort on the backend, though this never surfaces to the user since the client clears local state and navigates away regardless.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Authorization header missing, or not starting with &quot;Bearer &quot; -&gt; 401 INVALID_CREDENTIALS.</li><li>Expired or unparsable access token (header well-formed) -&gt; not an error; sign-out still returns 200.</li><li>Missing, expired, or unparsable refresh token -&gt; not an error; sign-out still returns 200.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user clicks &quot;Log out&quot; in the Navbar.</li><li>The client calls the logout endpoint with the Bearer header and refresh cookie sent automatically, without awaiting it, and swallows any rejection.</li><li>Independent of that outcome, the client clears local auth/workspace state and navigates to /login without waiting for the API response.</li><li>The backend validates the Authorization header format, strips the prefix, and calls the service.</li><li>The service parses the access token; on success it extracts the userId and blacklists the access token&#39;s jti.</li><li>If a refresh token is present, the service blacklists its jti too, independent of step 5&#39;s outcome.</li><li>If a userId was resolved in step 5, the service writes a LOGOUT audit log with ipAddress and userAgent.</li><li>The backend clears the refresh token cookie and returns 200 with no data.</li><li>By the time the response arrives, the user is typically already on /login; no toast is shown for the success case.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: Authorization header missing or malformed -&gt; the backend returns 401 INVALID_CREDENTIALS without calling the service. 4.a2: The frontend&#39;s error handler swallows it; the client still clears local state and navigates to /login with no user-facing error.</li><li>5.a1: Access token present but expired or fails to parse -&gt; caught and ignored; userId stays null; sign-out proceeds as idempotent success, no audit row written. 5.a2: Refresh token blacklisting still runs if present.</li><li>6.a1: Refresh token absent, expired, or fails to parse -&gt; caught and ignored; sign-out still returns 200.</li><li>N.a1: The logout call fails on the network (offline, timeout, server down) -&gt; the client proceeds exactly as in the success case: local state cleared, redirect to /login, no error toast; the server-side token remains valid until natural expiry.</li><li>N.a2: A 401 from any API call triggers a forced local-only logout with toast <strong>MSG22</strong> (&quot;session expired&quot;); this path does not call the logout endpoint.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The access token&#39;s and refresh token&#39;s jti values are blacklisted server-side (best-effort), the refresh cookie is cleared, and, when the access token was resolvable, a LOGOUT audit row exists.</li><li>Regardless of the API call&#39;s outcome, local auth/workspace state is cleared and the user is redirected to /login.</li><li>Sessions on other devices are unaffected.</li><li>If the API call failed, the server-side token may remain valid until natural expiry, but the user is signed out of the current browser session either way.</li></ul>",14)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
